fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    let mut lo: usize = 0;
    let mut hi: usize = v.len(); // exclusive

    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        let x = v[mid];
        if x < k {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }

    // Given the precondition that k appears at least once, lo must be in-bounds and v[lo] == k.
    debug_assert!(lo < v.len() && v[lo] == k);
    lo
}